def bound_state_derivative(y,z,cap):
 bound=(abs(z)>=cap)|(abs(y)>=cap);Dz=np.diag((~bound).astype(np.float32));Dc=np.where(bound,np.where(abs(y)>=cap,np.sign(y),np.sign(z)),np.float32(0));assert Dz.dtype==Dc.dtype==np.float32;return Dz,Dc
cases=[]
for y,z,cap,want in [(0.,0.,1.,1.),(0.,2.,1.,0.),(1.,.9999999,1.,0.),(-1.,-.9999999,1.,0.),(0.,0.,0.,0.)]:
 Dz,_=bound_state_derivative(np.array([y],np.float32),np.array([z],np.float32),np.float32(cap));assert float(Dz[0,0])==want;cases.append(dict(y=y,z=z,cap=cap,derivative=want))
(p/'bound-controls.json').write_text(json.dumps(dict(cases=cases),indent=2))

